     3	public enum Xpb98Status {
     4	    PENDING {
     5	        @Override
     6	        public boolean canTransitionTo(Xpb98Status nextStatus) {
     7	            return nextStatus == SHIPPED || nextStatus == CANCELED;
     8	        }
     9	    },
    10	    SHIPPED {
    11	        @Override
    12	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    13	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
    14	        }
    15	    },
    16	    IN_TRANSIT {
    17	        @Override
    18	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    19	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
    20	                    || nextStatus == DELIVERED;
    21	        }
    22	    },
    23	    OUT_FOR_DELIVERY {
    24	        @Override
    25	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    26	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
    27	        }
    28	    },
    29	    DELIVERED {
    30	        @Override
    31	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    32	            return false;
    33	        }
    34	    },
    35	    RETURNED {
    36	        @Override
    37	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    38	            return nextStatus == CANCELED;
    39	        }
    40	    },
    41	    CANCELED {
    42	        @Override
    43	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    44	            return false;
    45	        }
    46	    },
    47	    DELAYED {
    48	        @Override
    49	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    50	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
    51	        }
    52	    },
    53	    FAILED_DELIVERY {
    54	        @Override
    55	        public boolean canTransitionTo(Xpb98Status nextStatus) {
    56	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
    57	        }
