    62	    @Bean
    63	    public Step updateShipmentStatusesStep() {
    64	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
    66	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
    67	                .<Xhx14, Xhx14>chunk(CHUNK_SIZE, transactionManager)
    68	                .reader(shipmentItemReader())
    69	                .processor(new Xth19Processor(
    70	                        playwrightBrowserManager(),
    71	                        notificationService,
    72	                        orderService
    73	                ))
    74	                .writer(shipmentJpaItemWriter())
    75	                .faultTolerant()
    76	                .skip(Exception.class)
    77	                .skipLimit(SKIP_LIMIT)
    78	                .listener(shipmentSkipListener())
    80	                .listener(new Xmb36Listener(playwrightBrowserManager()))
    81	                .build();
    82	    }
    87	    @Bean
    88	    @StepScope
    89	    public JpaPagingItemReader<Xhx14> shipmentItemReader() {
    90	        log.debug("배송 상태 업데이트 ItemReader 구성");
    91	        return new JpaPagingItemReaderBuilder<Xhx14>()
    92	                .name("shipmentItemReader")
    93	                .entityManagerFactory(entityManagerFactory)
    94	                .pageSize(CHUNK_SIZE)
    95	                .queryString("SELECT s FROM Xhx14 s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
    96	                .build();
    97	    }
   104	    @Bean
   105	    @StepScope
   106	    public ItemProcessor<Xhx14, Xhx14> shipmentItemProcessor() {
